// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address u, uint128 amount) public {
        vm.assume(u != address(0));
        vm.assume(amount > 0);
        uint256 beforeBalance = c.getBalance(u);
        vm.deal(u, amount);
        vm.prank(u);
        c.addToBalance{value: amount}();
        uint256 afterBalance = c.getBalance(u);
        assertTrue(afterBalance == beforeBalance + amount);
    }
}
